"""Migration of legacy/opportunity_rules.vrl for OPP_MASTER validation."""

from decimal import Decimal


def _value(record: dict, field: str):
    """Return a legacy field value, treating missing and None as empty."""
    value = record.get(field, "")
    return "" if value is None else value


def _text(record: dict, field: str) -> str:
    return str(_value(record, field))


def _number(value) -> Decimal:
    """Apply legacy numeric coercion: empty values compare as zero."""
    if value == "" or value is None:
        return Decimal("0")
    return Decimal(str(value))


def _old_value(old: dict | None, event: str, field: str):
    """OLD fields are empty on INSERT."""
    if event != "UPDATE" or old is None:
        return ""
    value = old.get(field, "")
    return "" if value is None else value


def _date_greater_or_equal(left: str, right: str) -> bool:
    """Legacy date ordering, including the 00000000 null sentinel."""
    if left == "00000000" or right == "00000000":
        return False
    return left >= right


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Evaluate applicable opportunity rules in legacy rule-file order."""
    errors: list[dict] = []

    stat_cd = _text(record, "STAT_CD")
    amt = _number(_value(record, "AMT"))
    lost_rsn = _text(record, "LOST_RSN")
    close_dt = _text(record, "CLOSE_DT")
    stage_pct = _number(_value(record, "STAGE_PCT"))

    # OPP-001
    if event in ("INSERT", "UPDATE") and not (amt >= Decimal("0")):
        errors.append(
            {"code": "E3001", "message": "Amount negative", "severity": "BLOCK"}
        )

    # OPP-002
    if event in ("INSERT", "UPDATE") and not (
        not (stat_cd == "W" and amt == Decimal("0"))
    ):
        errors.append(
            {
                "code": "E3002",
                "message": "Won opportunity requires amount",
                "severity": "BLOCK",
            }
        )

    # OPP-003
    if event in ("INSERT", "UPDATE") and not (
        not (stat_cd == "L" and lost_rsn == "")
    ):
        errors.append(
            {"code": "E3003", "message": "Lost reason required", "severity": "BLOCK"}
        )

    # OPP-004
    if event in ("INSERT", "UPDATE") and not (
        not (stat_cd == "W" and close_dt == "00000000")
    ):
        errors.append(
            {
                "code": "E3004",
                "message": "Won opportunity requires close date",
                "severity": "BLOCK",
            }
        )

    # OPP-005
    old_stat_cd = str(_old_value(old, event, "STAT_CD"))
    if event == "UPDATE" and not (
        not (old_stat_cd == "W" and stat_cd != "W")
    ):
        errors.append(
            {
                "code": "E3005",
                "message": "Cannot reopen a won opportunity",
                "severity": "BLOCK",
            }
        )

    # OPP-006
    if event in ("INSERT", "UPDATE") and not (
        (stat_cd == "P" and stage_pct == Decimal("10"))
        or (stat_cd == "Q" and stage_pct == Decimal("25"))
        or (stat_cd == "N" and stage_pct == Decimal("60"))
        or (stat_cd == "W" and stage_pct == Decimal("100"))
        or (stat_cd == "L" and stage_pct == Decimal("0"))
    ):
        errors.append(
            {
                "code": "E3006",
                "message": "Stage percent inconsistent with status",
                "severity": "BLOCK",
            }
        )

    # OPP-007
    if event == "INSERT" and not (
        close_dt == "00000000" or _date_greater_or_equal(close_dt, str(today))
    ):
        errors.append(
            {"code": "E3007", "message": "Close date in past", "severity": "WARN"}
        )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected legacy validation failure is blocking."""
    return any(error.get("severity") == "BLOCK" for error in errors)
